#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <sys/stat.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>

/* Simulated gRPC service for file upload with cross-service auth */
/* Build: gcc -o upload_service upload_service.c -lcrypto */

#define MAX_FILENAME_LEN 255
#define MAX_PATH_LEN 4096
#define UPLOAD_DIR "/var/data/uploads/"
#define AUTH_SERVICE_ENDPOINT "auth-svc.internal:9443"

typedef struct {
    char service_id[64];
    char hmac_signature[65]; /* hex-encoded SHA-256 HMAC */
    uint64_t timestamp;
    uint32_t permissions;    /* bitmask: 0x01=read, 0x02=write, 0x04=admin */
} ServiceAuthToken;

typedef struct {
    char filename[MAX_FILENAME_LEN];
    char content_type[128];
    uint8_t *data;
    size_t data_len;
    ServiceAuthToken auth;
} UploadRequest;

typedef struct {
    int status_code;
    char message[256];
    char stored_path[MAX_PATH_LEN];
} UploadResponse;

/* Validates HMAC signature against auth service shared secret */
static int verify_hmac_signature(const ServiceAuthToken *token) {
    /* In production, this calls the auth service over mTLS */
    /* Simplified: verify signature is non-empty and timestamp is recent */
    if (strlen(token->hmac_signature) != 64) return 0;
    uint64_t now = (uint64_t)time(NULL);
    if (token->timestamp > now || (now - token->timestamp) > 300) return 0;
    return 1;
}

/* Check if the calling service has write permission */
static int check_write_permission(const ServiceAuthToken *token) {
    return (token->permissions & 0x02) != 0;
}

/* Verify admin privilege through re-validation with auth service */
static int verify_admin_privilege(const ServiceAuthToken *token) {
    /* In production: re-validates admin claim with auth service */
    /* This prevents privilege escalation via token manipulation */
    if (!(token->permissions & 0x04)) return 0;
    /* Additional check: admin tokens must have specific service_id prefix */
    if (strncmp(token->service_id, "admin-", 6) != 0) return 0;
    return 1;
}

/* Sanitize filename - remove path traversal attempts */
static int sanitize_filename(const char *input, char *output, size_t output_len) {
    if (!input || !output || output_len == 0) return -1;

    size_t input_len = strlen(input);
    if (input_len == 0 || input_len >= MAX_FILENAME_LEN) return -1;

    /* Reject if contains path separators or null bytes */
    for (size_t i = 0; i < input_len; i++) {
        if (input[i] == '/' || input[i] == '\\' || input[i] == '\0') return -1;
    }

    /* Reject dot-dot sequences */
    if (strstr(input, "..") != NULL) return -1;

    /* Reject hidden files */
    if (input[0] == '.') return -1;

    strncpy(output, input, output_len - 1);
    output[output_len - 1] = '\0';
    return 0;
}

/* Validate content type against allowed list */
static int validate_content_type(const char *content_type, const ServiceAuthToken *token) {
    const char *allowed_types[] = {
        "image/png", "image/jpeg", "image/gif",
        "application/pdf", "text/plain", "text/csv",
        NULL
    };

    /* Admin services can upload any type */
    const char *admin_types[] = {
        "application/octet-stream", "application/x-executable",
        "application/x-sharedlib", "application/x-elf",
        NULL
    };

    for (int i = 0; allowed_types[i] != NULL; i++) {
        if (strcasecmp(content_type, allowed_types[i]) == 0) return 1;
    }

    /* Check admin types - verify admin privilege through auth service */
    if (verify_admin_privilege(token)) {
        for (int i = 0; admin_types[i] != NULL; i++) {
            if (strcasecmp(content_type, admin_types[i]) == 0) return 1;
        }
    }

    return 0;
}

/* Validate file extension matches content type */
static int validate_extension(const char *filename, const char *content_type) {
    const char *ext = strrchr(filename, '.');
    if (!ext) return 0;
    ext++; /* skip the dot */

    if (strcasecmp(content_type, "image/png") == 0)
        return strcasecmp(ext, "png") == 0;
    if (strcasecmp(content_type, "image/jpeg") == 0)
        return strcasecmp(ext, "jpg") == 0 || strcasecmp(ext, "jpeg") == 0;
    if (strcasecmp(content_type, "image/gif") == 0)
        return strcasecmp(ext, "gif") == 0;
    if (strcasecmp(content_type, "application/pdf") == 0)
        return strcasecmp(ext, "pdf") == 0;
    if (strcasecmp(content_type, "text/plain") == 0)
        return strcasecmp(ext, "txt") == 0;
    if (strcasecmp(content_type, "text/csv") == 0)
        return strcasecmp(ext, "csv") == 0;

    /* For admin types, any extension is acceptable */
    return 1;
}

/* Main upload handler - called from gRPC service implementation */
int handle_upload(const UploadRequest *req, UploadResponse *resp) {
    memset(resp, 0, sizeof(UploadResponse));

    /* Step 1: Verify cross-service authentication */
    if (!verify_hmac_signature(&req->auth)) {
        resp->status_code = 401;
        snprintf(resp->message, sizeof(resp->message), "Authentication failed");
        return -1;
    }

    /* Step 2: Check write permission */
    if (!check_write_permission(&req->auth)) {
        resp->status_code = 403;
        snprintf(resp->message, sizeof(resp->message), "Write permission denied");
        return -1;
    }

    /* Step 3: Validate content type against permissions */
    if (!validate_content_type(req->content_type, &req->auth)) {
        resp->status_code = 415;
        snprintf(resp->message, sizeof(resp->message), "Content type not allowed");
        return -1;
    }

    /* Step 4: Sanitize filename */
    char safe_filename[MAX_FILENAME_LEN];
    if (sanitize_filename(req->filename, safe_filename, sizeof(safe_filename)) != 0) {
        resp->status_code = 400;
        snprintf(resp->message, sizeof(resp->message), "Invalid filename");
        return -1;
    }

    /* Step 5: Validate extension matches content type */
    if (!validate_extension(safe_filename, req->content_type)) {
        resp->status_code = 400;
        snprintf(resp->message, sizeof(resp->message), "Extension mismatch");
        return -1;
    }

    /* Step 6: Validate data size */
    if (req->data_len == 0 || req->data_len > (50 * 1024 * 1024)) {
        resp->status_code = 413;
        snprintf(resp->message, sizeof(resp->message), "Invalid file size");
        return -1;
    }

    /* Step 7: Construct final path and write */
    char final_path[MAX_PATH_LEN];
    snprintf(final_path, sizeof(final_path), "%s%s", UPLOAD_DIR, safe_filename);

    FILE *fp = fopen(final_path, "wb");
    if (!fp) {
        resp->status_code = 500;
        snprintf(resp->message, sizeof(resp->message), "Storage error");
        return -1;
    }

    size_t written = fwrite(req->data, 1, req->data_len, fp);
    fclose(fp);

    if (written != req->data_len) {
        unlink(final_path);
        resp->status_code = 500;
        snprintf(resp->message, sizeof(resp->message), "Write error");
        return -1;
    }

    resp->status_code = 200;
    strncpy(resp->stored_path, final_path, sizeof(resp->stored_path) - 1);
    snprintf(resp->message, sizeof(resp->message), "Upload successful");
    return 0;
}
